namespace App\Livewire;

use Livewire\Component;
use App\Models\Account;
use App\Services\PaymentGatewayService;
use Illuminate\Support\Facades\Auth;

class TransferFundsComponent extends Component
{
    public int $sourceAccountId;
    public string $destinationIban = '';
    public float $amount = 0.0;

    public function submitTransfer(PaymentGatewayService $gateway)
    {
        $sourceAccount = Auth::user()->accounts()->findOrFail($this->sourceAccountId);
        $this->authorize('transferFunds', $sourceAccount);

        $gateway->executeWire($sourceAccount, $this->destinationIban, $this->amount);
        session()->flash('message', 'Transfer executed successfully.');
    }

    public function render()
    {
        return view('livewire.transfer-funds');
    }
}
